import assert from 'node:assert/strict';
import { afterEach, describe, it, mock } from 'node:test';
import { SosClient } from '../../src/client';

// The API, stubbed at fetch: what the client asks for and how it reads the answer.
type Call = { url: string; headers: Record<string, string> };

function stubFetch(status: number, body: unknown): { calls: Call[] } {
  const calls: Call[] = [];
  mock.method(globalThis, 'fetch', async (url: string, init?: { headers?: Record<string, string> }) => {
    calls.push({ url, headers: init?.headers ?? {} });
    return new Response(JSON.stringify(body), { status, headers: { 'content-type': 'application/json' } });
  });
  return { calls };
}

const client = (sport?: 'boxing' | 'mma') =>
  new SosClient({ accessToken: 'key', amqpHost: 'amqp://unused', apiHost: 'https://api.example', sport });

const FIXTURE = {
  eventId: 'sr:match:72065192',
  sosId: '0b1f6c2e-3a4d-4c5e-9f70-1a2b3c4d5e6f',
  imgFightId: null,
  name: 'Katie Taylor vs Flora Pili',
  scheduledTime: null,
  status: 'SCHEDULED',
  competitors: [
    { id: 'sr:competitor:301560', name: 'TAYLOR, KATIE', qualifier: 'home', gender: 'female' },
    { id: 'sr:competitor:1361688', name: 'PILI, FLORA', qualifier: 'away' },
  ],
  sport: { id: 'sr:sport:10', name: 'Boxing' },
  card: null,
  tournament: null,
  weightClass: 'Jr. Welterweight',
  plannedRounds: null,
  isLiveOdds: true,
  updatedAt: '2026-09-16T18:15:19.780Z',
};

describe('fixtures through the SDK', () => {
  afterEach(() => mock.restoreAll());

  it('lists fixtures for the client sport, writing the wire names for the filters', async () => {
    const { calls } = stubFetch(200, { events: [FIXTURE] });

    const fixtures = await client('boxing').getFixtures({ date: '2026-09-15', status: 'SCHEDULED', isLiveOdds: true });

    assert.equal(calls[0].url, 'https://api.example/sos-api/v1/sports/boxing/events/json?date=2026-09-15&status=SCHEDULED&is_liveodds=true');
    assert.equal(calls[0].headers['X-API-Key'], 'key');
    assert.deepEqual(fixtures, [FIXTURE]);
    assert.equal(fixtures[0].competitors[0].gender, 'female');
    assert.equal(fixtures[0].competitors[1].gender, undefined);
    assert.equal(fixtures[0].scheduledTime, null);
  });

  it('still takes a bare date, as the old signature did, and defaults the sport to mma', async () => {
    const { calls } = stubFetch(200, { events: [] });
    assert.deepEqual(await client().getFixtures('2026-09-01'), []);
    assert.equal(calls[0].url, 'https://api.example/sos-api/v1/sports/mma/events/json?date=2026-09-01');
    await client().getFixtures();
    assert.equal(calls[1].url, 'https://api.example/sos-api/v1/sports/mma/events/json');
  });

  it('reads one fixture, escaping the id in the path, and answers null for one the feed does not hold', async () => {
    const found = stubFetch(200, FIXTURE);
    assert.deepEqual(await client('boxing').getFixture('sr:match:72065192'), FIXTURE);
    assert.equal(found.calls[0].url, 'https://api.example/sos-api/v1/sports/boxing/events/sr%3Amatch%3A72065192');
    mock.restoreAll();

    stubFetch(404, { error: 'Event not found' });
    assert.equal(await client('boxing').getFixture('sr:match:0'), null);
  });

  it('reads an event summary as JSON, and null when there is none', async () => {
    const summary = { fixture: FIXTURE, settled: true, settledMarkets: 2, lastSettlementAt: '2026-09-15T19:12:04.000Z', markets: [], generatedAt: '2026-09-15T19:15:00.000Z' };
    const { calls } = stubFetch(200, summary);
    assert.deepEqual(await client('boxing').getEventSummary('sr:match:72065192'), summary);
    assert.equal(calls[0].url, 'https://api.example/sos-api/v1/sports/boxing/events/sr%3Amatch%3A72065192/summary/json');
    mock.restoreAll();

    stubFetch(404, { error: 'Event not found' });
    assert.equal(await client('boxing').getEventSummary('sr:match:0'), null);
  });

  it('turns any other failure into an error naming the status and the url', async () => {
    stubFetch(500, { error: 'mongo unreachable' });
    await assert.rejects(client('boxing').getFixtures(), { message: /SOS API 500 for https:\/\/api\.example/ });
  });
});

import { EventEmitter } from 'events';
import { AmqpConnection } from './amqp/connection';
import { AmqpConsumer } from './amqp/consumer';
import { RecoveryManager } from './recovery/recoveryManager';
import { parseSosXml, detectMessageType } from './xml/parser';
import {
  EventSummary,
  Fixture,
  FixtureFilters,
  SosClientConfig,
  SosSport,
  SosEventMap,
  OddsChangeEvent,
  BetSettlementEvent,
  BetStopEvent,
  BetCancelEvent,
  FixtureChangeEvent,
  SnapshotCompleteEvent,
  AliveEvent,
} from './types';

const DEFAULT_SPORT: SosSport = 'mma';

// One feed carries one sport, so bind only that sport plus the shared alive stream.
function defaultBindingPatterns(sport: SosSport): string[] {
  return [`${sport}.live.#`, 'system.live.alive.#'];
}

export class SosClient extends EventEmitter {
  private amqpConnection: AmqpConnection;
  private consumer: AmqpConsumer;
  private recoveryManager: RecoveryManager;
  private config: Required<SosClientConfig>;

  constructor(userConfig: SosClientConfig) {
    super();

    this.config = {
      accessToken: userConfig.accessToken,
      amqpHost: userConfig.amqpHost,
      apiHost: userConfig.apiHost,
      sport: userConfig.sport ?? DEFAULT_SPORT,
      bindingPatterns:
        userConfig.bindingPatterns || defaultBindingPatterns(userConfig.sport ?? DEFAULT_SPORT),
      aliveTimeoutMs: userConfig.aliveTimeoutMs ?? 30000,
      autoRecover: userConfig.autoRecover ?? true,
    };

    this.amqpConnection = new AmqpConnection(this.config.amqpHost);
    this.consumer = new AmqpConsumer(
      this.amqpConnection,
      'swa.sos',
      this.config.bindingPatterns,
    );
    this.recoveryManager = new RecoveryManager(
      this.config.apiHost,
      this.config.accessToken,
      this.config.aliveTimeoutMs,
      this.config.autoRecover,
    );

    this.wireEvents();
  }

  /**
   * Connect to the SWA UOF feed.
   */
  async connect(): Promise<void> {
    await this.amqpConnection.connect();
  }

  /**
   * Disconnect from the feed.
   */
  async disconnect(): Promise<void> {
    this.recoveryManager.stopMonitoring();
    await this.consumer.stop();
    await this.amqpConnection.disconnect();
  }

  /**
   * Type-safe event listener.
   */
  on<K extends keyof SosEventMap>(
    event: K,
    listener: (data: SosEventMap[K]) => void,
  ): this {
    return super.on(event, listener);
  }

  emit<K extends keyof SosEventMap>(event: K, data?: SosEventMap[K]): boolean {
    return super.emit(event, data);
  }

  /**
   * Fetch market descriptions from the API (convenience method).
   */
  async getMarketDescriptions(): Promise<any> {
    const response = await fetch(
      `${this.config.apiHost}/sos-api/v1/descriptions/markets/json`,
      { headers: { 'X-API-Key': this.config.accessToken } },
    );
    return response.json();
  }

  /**
   * Every fixture the feed holds for this sport, filtered by date, status and whether
   * the feed will price it. A bare date string is still accepted, as before.
   */
  async getFixtures(filters: FixtureFilters | string = {}): Promise<Fixture[]> {
    const query = typeof filters === 'string' ? { date: filters } : filters;
    const params = new URLSearchParams();
    if (query.date) params.set('date', query.date);
    if (query.status) params.set('status', query.status);
    if (query.isLiveOdds !== undefined) params.set('is_liveodds', String(query.isLiveOdds));
    const suffix = params.size > 0 ? `?${params.toString()}` : '';
    const body = await this.getJson<{ events: Fixture[] }>(`${this.fixturesPath()}/json${suffix}`);
    return body?.events ?? [];
  }

  /**
   * One fixture by its event id, or null when the feed does not hold it.
   */
  async getFixture(eventId: string): Promise<Fixture | null> {
    return this.getJson<Fixture>(`${this.fixturesPath()}/${encodeURIComponent(eventId)}`);
  }

  /**
   * The fixture plus its result and settlement state, or null when the feed does not hold it.
   */
  async getEventSummary(eventId: string): Promise<EventSummary | null> {
    return this.getJson<EventSummary>(`${this.fixturesPath()}/${encodeURIComponent(eventId)}/summary/json`);
  }

  private fixturesPath(): string {
    return `${this.config.apiHost}/sos-api/v1/sports/${this.config.sport}/events`;
  }

  // A 404 is an answer (nothing held), any other failure is an error.
  private async getJson<T>(url: string): Promise<T | null> {
    const response = await fetch(url, { headers: { 'X-API-Key': this.config.accessToken } });
    if (response.status === 404) return null;
    if (!response.ok) throw new Error(`SOS API ${response.status} for ${url}`);
    return (await response.json()) as T;
  }

  private wireEvents(): void {
    // AMQP connection lifecycle
    this.amqpConnection.on('connected', async () => {
      console.log('[SosSDK] AMQP connected');
      try {
        await this.consumer.start();
        this.recoveryManager.startMonitoring();
        this.emit('connected');
      } catch (err: any) {
        console.error('[SosSDK] Failed to start consumer:', err);
        this.emit('error', err);
      }
    });

    this.amqpConnection.on('disconnected', () => {
      console.log('[SosSDK] AMQP disconnected');
      this.recoveryManager.stopMonitoring();
      this.emit('disconnected');
    });

    // AMQP message handling
    this.consumer.on('message', ({ xml }: { xml: string; routingKey: string }) => {
      this.handleMessage(xml);
    });

    // Recovery events
    this.recoveryManager.on('recoveryStarted', (data) => {
      this.emit('recoveryStarted', data);
    });

    this.recoveryManager.on('recoveryCompleted', () => {
      this.emit('recoveryCompleted');
    });

    this.recoveryManager.on('error', (err) => {
      this.emit('error', err);
    });
  }

  private handleMessage(xml: string): void {
    try {
      const msgType = detectMessageType(xml);
      const parsed = parseSosXml(xml);
      if (!parsed) return;

      switch (msgType) {
        case 'odds_change':
          this.emit('oddsChange', parsed as OddsChangeEvent);
          break;
        case 'bet_settlement':
          this.emit('betSettlement', parsed as BetSettlementEvent);
          break;
        case 'bet_stop':
          this.emit('betStop', parsed as BetStopEvent);
          break;
        case 'bet_cancel':
          this.emit('betCancel', parsed as BetCancelEvent);
          break;
        case 'fixture_change':
          this.emit('fixtureChange', parsed as FixtureChangeEvent);
          break;
        case 'snapshot_complete':
          this.emit('snapshotComplete', parsed as SnapshotCompleteEvent);
          break;
        case 'alive':
          this.recoveryManager.onAlive(parsed as AliveEvent);
          this.emit('alive', parsed as AliveEvent);
          break;
      }
    } catch (err: any) {
      console.error('[SosSDK] Failed to parse message:', err.message);
    }
  }
}

import amqplib, { ChannelModel, Channel } from 'amqplib';
import { EventEmitter } from 'events';

export class AmqpConnection extends EventEmitter {
  private connection: ChannelModel | null = null;
  private channel: Channel | null = null;
  private reconnectTimer: NodeJS.Timeout | null = null;
  private isIntentionallyClosed = false;
  private readonly reconnectDelayMs = 5000;

  constructor(private readonly amqpUrl: string) {
    super();
  }

  get isConnected(): boolean {
    return this.channel !== null;
  }

  getChannel(): Channel | null {
    return this.channel;
  }

  async connect(): Promise<void> {
    this.isIntentionallyClosed = false;
    await this.attemptConnection();
  }

  async disconnect(): Promise<void> {
    this.isIntentionallyClosed = true;
    if (this.reconnectTimer) {
      clearTimeout(this.reconnectTimer);
      this.reconnectTimer = null;
    }
    try {
      await this.channel?.close();
      await this.connection?.close();
    } catch {
      // ignore errors during shutdown
    }
    this.channel = null;
    this.connection = null;
  }

  private async attemptConnection(): Promise<void> {
    try {
      const conn = await amqplib.connect(this.amqpUrl);
      this.connection = conn;
      const ch = await conn.createChannel();
      this.channel = ch;

      conn.on('error', (err: Error) => {
        console.error('[SosSDK:AMQP] Connection error:', err.message);
      });

      conn.on('close', () => {
        this.channel = null;
        this.connection = null;
        this.emit('disconnected');
        this.scheduleReconnect();
      });

      this.emit('connected');
    } catch (err: any) {
      console.error('[SosSDK:AMQP] Connection failed:', err.message);
      this.scheduleReconnect();
    }
  }

  private scheduleReconnect(): void {
    if (this.isIntentionallyClosed) return;
    if (this.reconnectTimer) return;

    this.reconnectTimer = setTimeout(async () => {
      this.reconnectTimer = null;
      await this.attemptConnection();
    }, this.reconnectDelayMs);
  }
}

import { Channel, ConsumeMessage } from 'amqplib';
import { EventEmitter } from 'events';
import { AmqpConnection } from './connection';

export class AmqpConsumer extends EventEmitter {
  private queueName: string | null = null;
  private consumerTag: string | null = null;

  constructor(
    private connection: AmqpConnection,
    private exchange: string,
    private bindingPatterns: string[],
  ) {
    super();
  }

  /**
   * Set up the queue and start consuming messages.
   */
  async start(queuePrefix: string = 'swa.sos.sdk'): Promise<void> {
    const channel = this.connection.getChannel();
    if (!channel) throw new Error('AMQP not connected');

    // Exclusive, auto-delete queue for this SDK instance
    const q = await channel.assertQueue('', {
      exclusive: true,
      autoDelete: true,
    });
    this.queueName = q.queue;

    // Bind to the exchange with the specified patterns
    for (const pattern of this.bindingPatterns) {
      await channel.bindQueue(this.queueName, this.exchange, pattern);
    }

    // Start consuming
    const { consumerTag } = await channel.consume(
      this.queueName,
      (msg: ConsumeMessage | null) => {
        if (!msg) return;

        const xml = msg.content.toString('utf-8');
        const routingKey = msg.fields.routingKey;
        const headers = msg.properties.headers || {};

        this.emit('message', { xml, routingKey, headers });
        channel.ack(msg);
      },
      { noAck: false },
    );

    this.consumerTag = consumerTag;
  }

  async stop(): Promise<void> {
    const channel = this.connection.getChannel();
    if (channel && this.consumerTag) {
      try {
        await channel.cancel(this.consumerTag);
      } catch {
        // ignore
      }
    }
    this.consumerTag = null;
    this.queueName = null;
  }
}

import { EventEmitter } from 'events';
import { AliveEvent } from '../types';

export class RecoveryManager extends EventEmitter {
  private lastAliveAt: number = Date.now();
  private monitorTimer: NodeJS.Timeout | null = null;
  private isRecovering = false;

  constructor(
    private apiHost: string,
    private accessToken: string,
    private aliveTimeoutMs: number,
    private autoRecover: boolean,
  ) {
    super();
  }

  /**
   * Start monitoring alive messages.
   */
  startMonitoring(): void {
    this.lastAliveAt = Date.now();
    if (this.monitorTimer) return;

    this.monitorTimer = setInterval(() => {
      const elapsed = Date.now() - this.lastAliveAt;
      if (elapsed > this.aliveTimeoutMs && !this.isRecovering && this.autoRecover) {
        console.warn(`[SosSDK:Recovery] No alive for ${elapsed}ms — triggering recovery`);
        this.triggerRecovery();
      }
    }, 5000);
  }

  stopMonitoring(): void {
    if (this.monitorTimer) {
      clearInterval(this.monitorTimer);
      this.monitorTimer = null;
    }
  }

  /**
   * Called when an alive message is received.
   */
  onAlive(_event: AliveEvent): void {
    this.lastAliveAt = Date.now();
  }

  /**
   * Called on reconnect — requests recovery from the server.
   */
  async onReconnect(): Promise<void> {
    if (!this.autoRecover) return;
    await this.triggerRecovery();
  }

  private async triggerRecovery(): Promise<void> {
    if (this.isRecovering) return;
    this.isRecovering = true;

    try {
      const after = new Date(this.lastAliveAt).toISOString();
      const url = `${this.apiHost}/sos-api/recovery/1/initiate_request?after=${encodeURIComponent(after)}`;

      const response = await fetch(url, {
        method: 'POST',
        headers: {
          'X-API-Key': this.accessToken,
          'Content-Type': 'application/json',
        },
      });

      if (!response.ok) {
        throw new Error(`Recovery request failed: ${response.status} ${response.statusText}`);
      }

      const result = await response.json() as { requestId: string; estimatedMessages: number };
      this.emit('recoveryStarted', { estimatedMessages: result.estimatedMessages });

      // Poll for completion
      await this.pollRecoveryStatus(result.requestId);
    } catch (err) {
      console.error('[SosSDK:Recovery] Error:', err);
      this.emit('error', err);
    } finally {
      this.isRecovering = false;
    }
  }

  private async pollRecoveryStatus(requestId: string): Promise<void> {
    const maxAttempts = 60;
    for (let i = 0; i < maxAttempts; i++) {
      await new Promise(r => setTimeout(r, 2000));

      try {
        const url = `${this.apiHost}/sos-api/recovery/1/status?request_id=${encodeURIComponent(requestId)}`;
        const response = await fetch(url, {
          headers: { 'X-API-Key': this.accessToken },
        });

        if (!response.ok) continue;

        const status = await response.json() as { status: string };
        if (status.status === 'completed') {
          this.emit('recoveryCompleted');
          return;
        }
        if (status.status === 'failed') {
          this.emit('error', new Error('Recovery failed on server'));
          return;
        }
      } catch {
        // retry
      }
    }

    this.emit('error', new Error('Recovery polling timed out'));
  }
}

import { XMLParser } from 'fast-xml-parser';
import {
  OddsChangeEvent,
  BetSettlementEvent,
  BetStopEvent,
  BetCancelEvent,
  FixtureChangeEvent,
  SnapshotCompleteEvent,
  AliveEvent,
  Market,
  Outcome,
  SettlementMarket,
  SettlementOutcome,
} from '../types';

const xmlParser = new XMLParser({
  ignoreAttributes: false,
  attributeNamePrefix: '@_',
  allowBooleanAttributes: true,
  parseAttributeValue: true,
  isArray: (tagName) => ['market', 'outcome', 'competitor', 'result'].includes(tagName),
});

export function parseSosXml(
  xml: string,
): OddsChangeEvent | BetSettlementEvent | BetStopEvent | BetCancelEvent | FixtureChangeEvent | SnapshotCompleteEvent | AliveEvent | null {
  const parsed = xmlParser.parse(xml);

  if (parsed.odds_change) return parseOddsChange(parsed.odds_change);
  if (parsed.bet_settlement) return parseBetSettlement(parsed.bet_settlement);
  if (parsed.bet_stop) return parseBetStop(parsed.bet_stop);
  if (parsed.bet_cancel) return parseBetCancel(parsed.bet_cancel);
  if (parsed.fixture_change) return parseFixtureChange(parsed.fixture_change);
  if (parsed.snapshot_complete) return parseSnapshotComplete(parsed.snapshot_complete);
  if (parsed.alive) return parseAlive(parsed.alive);

  return null;
}

function parseOddsChange(oc: any): OddsChangeEvent {
  const markets: Market[] = [];

  const rawMarkets = oc.odds?.market || [];
  const marketArr = Array.isArray(rawMarkets) ? rawMarkets : [rawMarkets];

  for (const m of marketArr) {
    if (!m) continue;
    const rawOutcomes = m.outcome || [];
    const outcomeArr = Array.isArray(rawOutcomes) ? rawOutcomes : [rawOutcomes];

    const outcomes: Outcome[] = outcomeArr.map((o: any) => ({
      id: String(o['@_id']),
      odds: o['@_odds'] != null ? Number(o['@_odds']) : undefined,
      active: o['@_active'] === 1 || o['@_active'] === '1',
      probabilities: o['@_probabilities'] != null ? Number(o['@_probabilities']) : undefined,
    }));

    markets.push({
      id: Number(m['@_id']),
      specifiers: m['@_specifiers'] || undefined,
      status: Number(m['@_status']),
      outcomes,
    });
  }

  const ses = oc.sport_event_status || {};

  return {
    productId: Number(oc['@_product']),
    eventId: String(oc['@_event_id']),
    timestamp: Number(oc['@_timestamp']),
    sportEventStatus: {
      status: Number(ses['@_status'] ?? 0),
      matchStatus: Number(ses['@_match_status'] ?? 0),
      reporting: Number(ses['@_reporting'] ?? 0),
      clock: ses.clock ? {
        matchTime: ses.clock['@_match_time'],
        round: ses.clock['@_round'] != null ? Number(ses.clock['@_round']) : undefined,
      } : undefined,
    },
    markets,
  };
}

function parseBetSettlement(bs: any): BetSettlementEvent {
  const markets: SettlementMarket[] = [];

  const rawMarkets = bs.outcomes?.market || [];
  const marketArr = Array.isArray(rawMarkets) ? rawMarkets : [rawMarkets];

  for (const m of marketArr) {
    if (!m) continue;
    const rawOutcomes = m.outcome || [];
    const outcomeArr = Array.isArray(rawOutcomes) ? rawOutcomes : [rawOutcomes];

    const outcomes: SettlementOutcome[] = outcomeArr.map((o: any) => {
      const resultCode = String(o['@_result']);
      let result: SettlementOutcome['result'] = 'undecided';
      if (resultCode === '1') result = 'won';
      else if (resultCode === '0') result = 'lost';
      else if (resultCode === '-1') result = 'void';

      return {
        id: String(o['@_id']),
        result,
        voidFactor: o['@_void_factor'] != null && o['@_void_factor'] !== '' ? Number(o['@_void_factor']) : undefined,
        deadHeatFactor: o['@_dead_heat_factor'] != null && o['@_dead_heat_factor'] !== '' ? Number(o['@_dead_heat_factor']) : undefined,
      };
    });

    markets.push({
      id: Number(m['@_id']),
      specifiers: m['@_specifiers'] || undefined,
      voidReason: m['@_void_reason'] || undefined,
      outcomes,
    });
  }

  return {
    productId: Number(bs['@_product']),
    eventId: String(bs['@_event_id']),
    timestamp: Number(bs['@_timestamp']),
    certainty: Number(bs['@_certainty'] ?? 1),
    markets,
  };
}

function parseBetStop(stop: any): BetStopEvent {
  return {
    productId: Number(stop['@_product']),
    eventId: String(stop['@_event_id']),
    timestamp: Number(stop['@_timestamp']),
    groups: String(stop.groups || 'all'),
  };
}

function parseBetCancel(bc: any): BetCancelEvent {
  const rawMarkets = bc.market || [];
  const marketArr = Array.isArray(rawMarkets) ? rawMarkets : [rawMarkets];

  return {
    productId: Number(bc['@_product']),
    eventId: String(bc['@_event_id']),
    timestamp: Number(bc['@_timestamp']),
    startTime: bc['@_start_time'] != null ? Number(bc['@_start_time']) : undefined,
    endTime: bc['@_end_time'] != null ? Number(bc['@_end_time']) : undefined,
    markets: marketArr.filter(Boolean).map((m: any) => ({
      id: Number(m['@_id']),
      voidReason: m['@_void_reason'] != null ? m['@_void_reason'] : undefined,
    })),
  };
}

function parseFixtureChange(fc: any): FixtureChangeEvent {
  return {
    productId: Number(fc['@_product']),
    eventId: String(fc['@_event_id']),
    timestamp: Number(fc['@_timestamp']),
    startTime: fc['@_start_time'] != null ? Number(fc['@_start_time']) : undefined,
  };
}

function parseSnapshotComplete(sc: any): SnapshotCompleteEvent {
  return {
    productId: Number(sc['@_product']),
    requestId: String(sc['@_request_id']),
    timestamp: Number(sc['@_timestamp']),
  };
}

function parseAlive(alive: any): AliveEvent {
  return {
    productId: Number(alive['@_product']),
    timestamp: Number(alive['@_timestamp']),
    subscribed: alive['@_subscribed'] === 1 || alive['@_subscribed'] === '1',
  };
}

/**
 * Detect message type from raw XML without full parse.
 */
export function detectMessageType(xml: string): string | null {
  if (xml.includes('<odds_change')) return 'odds_change';
  if (xml.includes('<bet_settlement')) return 'bet_settlement';
  if (xml.includes('<bet_stop')) return 'bet_stop';
  if (xml.includes('<bet_cancel')) return 'bet_cancel';
  if (xml.includes('<fixture_change')) return 'fixture_change';
  if (xml.includes('<snapshot_complete')) return 'snapshot_complete';
  if (xml.includes('<alive')) return 'alive';
  return null;
}
